-- Executar após 001_schema.sql. Dados reais nunca fazem parte da migração.
ALTER TABLE leads ADD COLUMN IF NOT EXISTS protocol text;
ALTER TABLE leads ADD COLUMN IF NOT EXISTS consent_version text;
ALTER TABLE leads ADD COLUMN IF NOT EXISTS request_key uuid;
ALTER TABLE leads ADD COLUMN IF NOT EXISTS assigned_to uuid REFERENCES app_users(id);
ALTER TABLE leads ADD COLUMN IF NOT EXISTS case_id uuid REFERENCES cases(id);
ALTER TABLE leads ADD COLUMN IF NOT EXISTS internal_note_ciphertext text;
CREATE UNIQUE INDEX IF NOT EXISTS leads_request_unique ON leads(request_key);
CREATE UNIQUE INDEX IF NOT EXISTS leads_protocol_unique ON leads(protocol);
ALTER TABLE case_files ADD COLUMN IF NOT EXISTS evidence_reviewed_by uuid REFERENCES app_users(id);
ALTER TABLE case_files ADD COLUMN IF NOT EXISTS evidence_reviewed_at timestamptz;
ALTER TABLE case_files ADD COLUMN IF NOT EXISTS organization text CHECK(organization IN ('SPC','SERASA','BOA_VISTA','PROTESTOS'));
CREATE TABLE IF NOT EXISTS request_limits(key text PRIMARY KEY,window_start timestamptz NOT NULL,hits integer NOT NULL);
CREATE TABLE IF NOT EXISTS access_invites(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),token_hash text NOT NULL UNIQUE,email text NOT NULL,full_name text NOT NULL,role text NOT NULL CHECK(role IN ('client','operator','admin','auditor')),client_id uuid REFERENCES clients(id),created_by uuid REFERENCES app_users(id),expires_at timestamptz NOT NULL,used_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
DO $$ BEGIN IF NOT EXISTS(SELECT FROM pg_roles WHERE rolname='sauvid_runtime') THEN CREATE ROLE sauvid_runtime NOLOGIN; END IF; END $$;
GRANT sauvid_runtime TO CURRENT_USER;
GRANT USAGE ON SCHEMA public TO sauvid_runtime;
GRANT SELECT,INSERT,UPDATE ON clients,cases,case_organizations,case_events,case_files,leads TO sauvid_runtime;
GRANT SELECT ON app_users,client_access TO sauvid_runtime;
GRANT SELECT,INSERT,UPDATE ON request_limits TO sauvid_runtime;
GRANT SELECT,INSERT,UPDATE ON access_invites TO sauvid_runtime;
GRANT SELECT,INSERT ON audit_log TO sauvid_runtime;
GRANT USAGE,SELECT ON SEQUENCE audit_log_id_seq TO sauvid_runtime;
CREATE OR REPLACE FUNCTION app_actor() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('app.user_id',true),'')::uuid $$;
CREATE OR REPLACE FUNCTION app_staff() RETURNS boolean LANGUAGE sql STABLE AS $$ SELECT coalesce(current_setting('app.role',true),'') IN ('admin','operator','auditor') $$;
CREATE OR REPLACE FUNCTION app_writer() RETURNS boolean LANGUAGE sql STABLE AS $$ SELECT coalesce(current_setting('app.role',true),'') IN ('admin','operator') $$;
CREATE OR REPLACE FUNCTION app_client_allowed(target uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT app_staff() OR EXISTS(SELECT 1 FROM client_access ca JOIN app_users au ON au.id=ca.user_id WHERE ca.user_id=app_actor() AND ca.client_id=target AND au.active) $$;
CREATE OR REPLACE FUNCTION app_case_allowed(target uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT EXISTS(SELECT 1 FROM cases c WHERE c.id=target AND app_client_allowed(c.client_id)) $$;
ALTER TABLE app_users ENABLE ROW LEVEL SECURITY;
ALTER TABLE client_access ENABLE ROW LEVEL SECURITY;
ALTER TABLE clients ENABLE ROW LEVEL SECURITY;
ALTER TABLE cases ENABLE ROW LEVEL SECURITY;
ALTER TABLE case_organizations ENABLE ROW LEVEL SECURITY;
ALTER TABLE case_events ENABLE ROW LEVEL SECURITY;
ALTER TABLE case_files ENABLE ROW LEVEL SECURITY;
ALTER TABLE leads ENABLE ROW LEVEL SECURITY;
ALTER TABLE audit_log ENABLE ROW LEVEL SECURITY;
ALTER TABLE access_invites ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS users_read ON app_users;
CREATE POLICY users_read ON app_users FOR SELECT TO sauvid_runtime USING(id=app_actor() OR app_staff());
DROP POLICY IF EXISTS access_read ON client_access;
CREATE POLICY access_read ON client_access FOR SELECT TO sauvid_runtime USING(user_id=app_actor() OR app_staff());
DROP POLICY IF EXISTS clients_read ON clients;
CREATE POLICY clients_read ON clients FOR SELECT TO sauvid_runtime USING(app_client_allowed(id));
DROP POLICY IF EXISTS clients_write ON clients;
CREATE POLICY clients_write ON clients FOR ALL TO sauvid_runtime USING(app_writer()) WITH CHECK(app_writer());
DROP POLICY IF EXISTS cases_read ON cases;
CREATE POLICY cases_read ON cases FOR SELECT TO sauvid_runtime USING(app_client_allowed(client_id));
DROP POLICY IF EXISTS cases_write ON cases;
CREATE POLICY cases_write ON cases FOR ALL TO sauvid_runtime USING(app_writer()) WITH CHECK(app_writer());
DROP POLICY IF EXISTS org_read ON case_organizations;
CREATE POLICY org_read ON case_organizations FOR SELECT TO sauvid_runtime USING(app_case_allowed(case_id));
DROP POLICY IF EXISTS org_write ON case_organizations;
CREATE POLICY org_write ON case_organizations FOR ALL TO sauvid_runtime USING(app_writer()) WITH CHECK(app_writer());
DROP POLICY IF EXISTS events_read ON case_events;
CREATE POLICY events_read ON case_events FOR SELECT TO sauvid_runtime USING(app_case_allowed(case_id) AND (visibility='client' OR app_staff()));
DROP POLICY IF EXISTS events_write ON case_events;
CREATE POLICY events_write ON case_events FOR ALL TO sauvid_runtime USING(app_writer()) WITH CHECK(app_writer());
DROP POLICY IF EXISTS files_read ON case_files;
CREATE POLICY files_read ON case_files FOR SELECT TO sauvid_runtime USING(app_case_allowed(case_id) AND (visibility='client' OR app_staff()));
DROP POLICY IF EXISTS files_write ON case_files;
CREATE POLICY files_write ON case_files FOR ALL TO sauvid_runtime USING(app_writer()) WITH CHECK(app_writer());
DROP POLICY IF EXISTS leads_read ON leads;
CREATE POLICY leads_read ON leads FOR SELECT TO sauvid_runtime USING(app_staff());
DROP POLICY IF EXISTS leads_insert ON leads;
CREATE POLICY leads_insert ON leads FOR INSERT TO sauvid_runtime WITH CHECK(true);
DROP POLICY IF EXISTS leads_update ON leads;
CREATE POLICY leads_update ON leads FOR UPDATE TO sauvid_runtime USING(app_writer()) WITH CHECK(app_writer());
DROP POLICY IF EXISTS audit_read ON audit_log;
CREATE POLICY audit_read ON audit_log FOR SELECT TO sauvid_runtime USING(current_setting('app.role',true) IN ('admin','auditor'));
DROP POLICY IF EXISTS audit_append ON audit_log;
CREATE POLICY audit_append ON audit_log FOR INSERT TO sauvid_runtime WITH CHECK(actor_user_id IS NOT DISTINCT FROM app_actor());
DROP POLICY IF EXISTS invites_admin ON access_invites;
CREATE POLICY invites_admin ON access_invites FOR ALL TO sauvid_runtime USING(current_setting('app.role',true)='admin') WITH CHECK(current_setting('app.role',true)='admin');
CREATE OR REPLACE FUNCTION immutable_audit() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Audit log is append only'; END $$;
DROP TRIGGER IF EXISTS audit_immutable ON audit_log;
CREATE TRIGGER audit_immutable BEFORE UPDATE OR DELETE ON audit_log FOR EACH ROW EXECUTE FUNCTION immutable_audit();
CREATE OR REPLACE FUNCTION operation_audit() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN INSERT INTO audit_log(actor_user_id,action,entity_type,entity_id,metadata) VALUES(app_actor(),lower(TG_OP),TG_TABLE_NAME,NEW.id::text,jsonb_build_object('at',now()));RETURN NEW;END $$;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['clients','cases','case_organizations','case_events','case_files','leads','access_invites'] LOOP EXECUTE format('DROP TRIGGER IF EXISTS operation_audit ON %I',t);EXECUTE format('CREATE TRIGGER operation_audit AFTER INSERT OR UPDATE ON %I FOR EACH ROW EXECUTE FUNCTION operation_audit()',t);END LOOP; END $$;
CREATE OR REPLACE FUNCTION protect_event() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF OLD.visibility='client' AND (NEW.title IS DISTINCT FROM OLD.title OR NEW.message IS DISTINCT FROM OLD.message OR NEW.occurred_at IS DISTINCT FROM OLD.occurred_at) THEN RAISE EXCEPTION 'Published history cannot be overwritten'; END IF; RETURN NEW;END $$;
DROP TRIGGER IF EXISTS protect_published_event ON case_events;
CREATE TRIGGER protect_published_event BEFORE UPDATE ON case_events FOR EACH ROW EXECUTE FUNCTION protect_event();
CREATE OR REPLACE FUNCTION protect_confirmation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.status_code='confirmed' AND (NEW.evidence_state NOT IN ('reviewed','confirmed') OR NOT EXISTS(SELECT 1 FROM case_files f WHERE f.case_id=NEW.case_id AND f.organization=NEW.organization AND f.evidence_reviewed_by IS NOT NULL)) THEN RAISE EXCEPTION 'Confirmed status requires reviewed evidence'; END IF;RETURN NEW;END $$;
DROP TRIGGER IF EXISTS require_confirmation_evidence ON case_organizations;
CREATE TRIGGER require_confirmation_evidence BEFORE INSERT OR UPDATE ON case_organizations FOR EACH ROW EXECUTE FUNCTION protect_confirmation();
-- Inserção idempotente sem conceder leitura pública de solicitações.
CREATE OR REPLACE FUNCTION receive_lead(p_id uuid,p_name text,p_email text,p_whatsapp text,p_lookup text,p_cpf text,p_last4 text,p_situation text,p_protocol text,p_request uuid) RETURNS TABLE(protocol text,inserted boolean) LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE count_rows integer; BEGIN
 INSERT INTO leads(id,name,email,whatsapp,cpf_lookup_hash,cpf_ciphertext,cpf_last4,situation_ciphertext,protocol,consent_version,request_key) VALUES(p_id,p_name,p_email,p_whatsapp,p_lookup,p_cpf,p_last4,p_situation,p_protocol,'2026-10-12',p_request) ON CONFLICT(request_key) DO NOTHING;
 GET DIAGNOSTICS count_rows=ROW_COUNT;
 RETURN QUERY SELECT l.protocol,count_rows=1 FROM leads l WHERE l.request_key=p_request;
END $$;
REVOKE ALL ON FUNCTION receive_lead(uuid,text,text,text,text,text,text,text,text,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION receive_lead(uuid,text,text,text,text,text,text,text,text,uuid) TO sauvid_runtime;
REVOKE INSERT ON leads FROM sauvid_runtime;
CREATE OR REPLACE FUNCTION change_user_access(target uuid,enabled boolean,new_role text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ BEGIN
 IF current_setting('app.role',true)<>'admin' OR target=app_actor() OR new_role NOT IN ('client','operator','admin','auditor') THEN RAISE EXCEPTION 'Access change denied'; END IF;
 UPDATE app_users SET active=enabled,role=new_role,updated_at=now() WHERE id=target;
 IF NOT FOUND THEN RAISE EXCEPTION 'User not found'; END IF;
 DELETE FROM session WHERE "userId"=(SELECT auth_subject FROM app_users WHERE id=target);
 INSERT INTO audit_log(actor_user_id,action,entity_type,entity_id,metadata) VALUES(app_actor(),'access_change','app_users',target::text,jsonb_build_object('active',enabled,'role',new_role));
END $$;
REVOKE ALL ON FUNCTION change_user_access(uuid,boolean,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION change_user_access(uuid,boolean,text) TO sauvid_runtime;
